import random, json, subprocess, sys
random.seed(1234)
def rnd_ranges(maxv):
    r=[]
    for _ in range(random.randint(0,3)):
        lo=random.randint(0,maxv); hi=random.randint(lo,maxv); r.append([lo,hi])
    return r
def rnd_frame(level):
    types=['PADDING','PING','ACK','CRYPTO','STREAM','RESET_STREAM','STOP_SENDING','CLOSE','HANDSHAKE_DONE','UNKNOWN']
    t=random.choice(types)
    if t in ('PADDING','PING','HANDSHAKE_DONE','UNKNOWN'): return {'type':t}
    if t=='ACK': return {'type':'ACK','ranges':rnd_ranges(20)}
    if t=='CRYPTO': return {'type':'CRYPTO','offset':random.randint(0,30),'data_hex':''.join(random.choice('abcdef0123456789') for _ in range(2*random.randint(0,4)))}
    if t=='STREAM': return {'type':'STREAM','id':random.randint(0,12),'offset':random.randint(0,10),'data_hex':''.join(random.choice('abcdef0123456789') for _ in range(2*random.randint(0,4))),'fin':random.choice([True,False])}
    if t=='RESET_STREAM': return {'type':'RESET_STREAM','id':random.randint(0,12),'final_size':random.randint(0,20)}
    if t=='STOP_SENDING': return {'type':'STOP_SENDING','id':random.randint(0,12)}
    if t=='CLOSE': return {'type':'CLOSE','app':random.choice([True,False]),'code':random.randint(0,20)}
def rnd_packet():
    return {'level':random.choice('IHZA'),'pn':random.randint(0,20),'auth':random.choice([True,False]),'frames':[rnd_frame(None) for _ in range(random.randint(0,4))]}
def rnd_trace(i):
